SELECT h.ORDNUM,h.ORDSEQ,c.CUSTNM,d.LASTDT FROM SA100T h LEFT OUTER JOIN BA020T c ON h.CUSTCD=c.CUSTCD LEFT OUTER JOIN (SELECT t.ORDNUM,t.ORDSEQ,MAX(t.RECDT) AS LASTDT FROM SA210T t WHERE t.OUTKIND='C' GROUP BY t.ORDNUM,t.ORDSEQ) d ON h.ORDNUM=d.ORDNUM AND h.ORDSEQ=d.ORDSEQ WHERE h.REMARK<>N'조건 유지' -- 사용자 주석
